INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (224, 'math', 1, 'problem_solving', 'statistical_claims', 'easy', 'The members of a city council wanted to assess the opinions of all city

residents about converting an open field into a dog park. The council

surveyed a sample of 500 city residents who own dogs. The survey showed
that the majority of those sampled were in favor of the dog park. Which of
the following is true about the city council''s survey?', NULL, '["It shows that the majority of city residents are in favor of the dog park.", "The survey sample should have included more residents who are dog owners.", "The survey sample should have consisted entirely of residents who do not own dogs.", "The survey sample is biased because it is not representative of all city residents."]', 3, 'The correct answer is D. This question requires understanding of evaluating statistical claims concepts.', 'This question tests your understanding of Evaluating Statistical Claims. Problem-Solving and Data Analysis is one of the key content domains on the SAT.', 'Practice more Evaluating Statistical Claims problems to strengthen your skills in this area.', 1, 120, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (225, 'math', 2, 'problem_solving', 'statistical_claims', 'easy', 'A market researcher selected 200 people at random from a group of people
who indicated that they liked a certain book. The 200 people were shown a
movie based on the book and then asked whether they liked or disliked the
movie. Of those surveyed, 95% said they disliked the movie. Which of the
following inferences can appropriately be drawn from this survey result?', NULL, '["At least 95% of people who go see movies will dislike this movie.", "At least 95% of people who read books will dislike this movie.", "Most people who dislike this book will like this movie.", "Most people who like this book will dislike this movie."]', 3, 'The correct answer is D. This question requires understanding of evaluating statistical claims concepts.', 'This question tests your understanding of Evaluating Statistical Claims. Problem-Solving and Data Analysis is one of the key content domains on the SAT.', 'Practice more Evaluating Statistical Claims problems to strengthen your skills in this area.', 1, 120, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (226, 'math', 1, 'problem_solving', 'statistical_claims', 'medium', 'Residents of a town were surveyed to determine whether they are satisfied

with the concession stand at the local park. A random sample of

200 residents was selected. All 200 responded, and 87% said they are

satisfied. Based on this information, which of the following statements

must be true?

|. Of all the town residents, 87% would say they are satisfied with the concession stand at the local park.
ll. If another random sample of 200 residents were surveyed, 87% would say they are satisfied.', NULL, '["Neither", "| only", "Il only", "| and Il"]', 0, 'The correct answer is A. This question requires understanding of evaluating statistical claims concepts.', 'This question tests your understanding of Evaluating Statistical Claims. Problem-Solving and Data Analysis is one of the key content domains on the SAT.', 'Practice more Evaluating Statistical Claims problems to strengthen your skills in this area.', 1, 120, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (227, 'math', 2, 'problem_solving', 'statistical_claims', 'medium', 'A survey was conducted using a sample of history professors selected at
random from the California State Universities. The professors surveyed
were asked to name the publishers of their current texts. What is the largest
population to which the results of the survey can be generalized?', NULL, '["All professors in the United States", "All history professors in the United States", "All history professors at all California State Universities", "All professors at all California State Universities"]', 2, 'The correct answer is C. This question requires understanding of evaluating statistical claims concepts.', 'This question tests your understanding of Evaluating Statistical Claims. Problem-Solving and Data Analysis is one of the key content domains on the SAT.', 'Practice more Evaluating Statistical Claims problems to strengthen your skills in this area.', 1, 120, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (228, 'math', 1, 'problem_solving', 'statistical_claims', 'medium', 'A polling agency recently surveyed 1,000 adults who were selected at
random from a large city and asked each of the adults, "Are you satisfied
with the quality of air in the city?" Of those surveyed, 78 percent responded
that they were satisfied with the quality of air in the city. Based on the
results of the survey, which of the following statements must be true?
1. Of all adults in the city, 78 percent are satisfied with the quality of air in the city.
2. If another 1,000 adults selected at random from the city were surveyed, 78 percent of them would report
they are satisfied with the quality of air in the city.
3. If 1,000 adults selected at random from a different city were surveyed, 78 percent of them would report they
are satisfied with the quality of air in the city.', NULL, '["None", "Il only", "| and Il only", "| and III only"]', 0, 'The correct answer is A. This question requires understanding of evaluating statistical claims concepts.', 'This question tests your understanding of Evaluating Statistical Claims. Problem-Solving and Data Analysis is one of the key content domains on the SAT.', 'Practice more Evaluating Statistical Claims problems to strengthen your skills in this area.', 1, 120, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (229, 'math', 1, 'problem_solving', 'statistical_claims', 'medium', 'A sample of 40 fourth-grade students was selected at random from a
certain school. The 40 students completed a survey about the morning
announcements, and 32 thought the announcements were helpful. Which of
