INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (296, 'math', 2, 'problem_solving', 'probability', 'medium', 'On May 10, 2015, there were 83 million Internet subscribers in Nigeria. The
