INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (350, 'math', 1, 'geometry', 'area_volume', 'easy', 'The side length of a square is 55 centimeters (cm). What is the area, in cm², of the square?', NULL, '["110", "220", "3,025", "12,100"]', 2, 'The correct answer is C. This question requires understanding of area and volume concepts.', 'This question tests your understanding of Area and Volume. Geometry and Trigonometry is one of the key content domains on the SAT.', 'Practice more Area and Volume problems to strengthen your skills in this area.', 1, 120, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (351, 'math', 1, 'geometry', 'area_volume', 'easy', 'Triangle ABC and triangle DEF are similar triangles, where AB and DE are
corresponding sides. If DE =2AB and the perimeter of triangle ABC is 20,
what is the perimeter of triangle DEF ?', NULL, '["10", "40", "80", "120"]', 1, 'The correct answer is B. This question requires understanding of area and volume concepts.', 'This question tests your understanding of Area and Volume. Geometry and Trigonometry is one of the key content domains on the SAT.', 'Practice more Area and Volume problems to strengthen your skills in this area.', 1, 120, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (352, 'math', 2, 'geometry', 'area_volume', 'easy', 'A rectangle has a length of 13 and a width of 6. What is the perimeter of the rectangle?', NULL, '["12", "26", "38", "52"]', 2, 'The correct answer is C. This question requires understanding of area and volume concepts.', 'This question tests your understanding of Area and Volume. Geometry and Trigonometry is one of the key content domains on the SAT.', 'Practice more Area and Volume problems to strengthen your skills in this area.', 1, 120, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (353, 'math', 2, 'geometry', 'area_volume', 'easy', 'What is the area of a rectangle with a length of 4 centimeters (cm) and a width of 2 cm?', NULL, '["6 cm?", "8cm?", "12 cm?", "36 cm?"]', 1, 'The correct answer is B. This question requires understanding of area and volume concepts.', 'This question tests your understanding of Area and Volume. Geometry and Trigonometry is one of the key content domains on the SAT.', 'Practice more Area and Volume problems to strengthen your skills in this area.', 1, 120, '[]');
