INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (355, 'math', 1, 'geometry', 'area_volume', 'medium', 'A triangle has a base length of 40 centimeters and a height of 90 centimeters. What is the area, in square centimeters, of the
