INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (356, 'math', 1, 'geometry', 'area_volume', 'medium', 'What is the area of a rectangle with a length of 17 centimeters (cm) and a width of 7 cm?', NULL, '["24cm?", "48 cm?", "119 cm?", "576 cm?"]', 2, 'The correct answer is C. This question requires understanding of area and volume concepts.', 'This question tests your understanding of Area and Volume. Geometry and Trigonometry is one of the key content domains on the SAT.', 'Practice more Area and Volume problems to strengthen your skills in this area.', 1, 120, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (357, 'math', 1, 'geometry', 'area_volume', 'medium', 'A rectangle has a length of 3 units and a width of 39 units. Which expression gives the area, in square units, of this
