INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (358, 'math', 2, 'geometry', 'area_volume', 'medium', 'A right rectangular prism has a length of 11 meters, a width of 8 meters, and a height of 10 meters. What is the volume, in
