INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (359, 'math', 2, 'geometry', 'area_volume', 'medium', 'Triangle R has an area of 80 square centimeters (cm?). Square S has side lengths of 4 cm. What is the total area of
