INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (360, 'math', 1, 'geometry', 'area_volume', 'medium', 'What is the volume, in cubic centimeters, of a right rectangular prism that
has a length of 4 centimeters, a width of 9 centimeters, and a height of
10 centimeters?', NULL, '["360", "0", "1", "-1"]', 0, 'The correct answer is 360. This is a student-produced response question testing area and volume.', 'This question tests your understanding of Area and Volume. Geometry and Trigonometry is one of the key content domains on the SAT.', 'Practice more Area and Volume problems to strengthen your skills in this area.', 1, 120, '["student_produced_response"]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (361, 'math', 2, 'geometry', 'area_volume', 'medium', 'A manufacturing company produces two sizes of cylindrical containers that
each have a height of 50 centimeters. The radius of container A is 16
