INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (890, 'reading_writing', 1, 'craft_structure', 'words_context', 'medium', 'As used in the text, what does the word "endure" most nearly mean?', 'The following text is adapted from Oscar Wilde''s 1895 play The Importance of Being Earnest.
