INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (897, 'reading_writing', 1, 'craft_structure', 'words_context', 'hard', 'Which choice completes the text with the most logical and precise word or phrase?', 'In a study of residential mobility in Washington, DC, LaTanya Brown-Robertson et al. found that increases in household
