INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (898, 'reading_writing', 2, 'craft_structure', 'words_context', 'hard', 'Which choice completes the text with the most logical and precise word or phrase?', 'Businesses typically try to promote themselves, but research by Michael Luca, Abhishek Nagaraj, and Gauri Subramani
