INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (998, 'reading_writing', 2, 'expression', 'transitions', 'easy', 'Which choice completes the text with the most logical transition?', 'In June, female loggerhead sea turtles will swim back to the sandy beaches where they were born to lay eggs of
their own. First, the turtle will dig her nest in the sand. she will lay up to 100 eggs in the nest. Finally, she
will cover it all with sand, before returning to the ocean.', '["By contrast,", "Similarly,", "Next,", "For example,"]', 2, 'The correct answer is C. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (999, 'reading_writing', 1, 'expression', 'transitions', 'easy', 'Which choice completes the text with the most logical transition?', 'Practical movie effects, such as the use of actual locations in a film, provide a more realistic visual experience
than computer-generated imagery (CGI) does, but giving audiences the "real thing" can be prohibitively
expensive. many filmmakers use a blended approach, employing practical effects whenever possible and
CGI elements as necessary to control costs.', '["Similarly,", "For this reason,", "Furthermore,", "In other words,"]', 1, 'The correct answer is B. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1000, 'reading_writing', 2, 'expression', 'transitions', 'easy', 'Which choice completes the text with the most logical transition?', 'In the 1850s, William Still was instrumental in helping nearly 1,000 people escape from slavery, earning him the
moniker "the Father of the Underground Railroad." despite the fame of his contributions during his lifetime,
Still is discussed far less today than other prominent Black abolitionists from his era, such as Frederick Douglass
and Harriet Tubman.', '["For example,", "However,", "Specifically,", "Similarly,"]', 1, 'The correct answer is B. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1001, 'reading_writing', 1, 'expression', 'transitions', 'medium', 'Which choice completes the text with the most logical transition?', 'In 2018, Kurt Luther and Vikram Mohanty created the web-based tool Civil War Photo Sleuth (CWPS). A user
uploading an unknown Civil War soldier''s photograph to CWPS first tags the photo with all known information.
CWPS''s facial-recognition software analyzes twenty-seven different physical features and looks for

matches to tagged images already in the database.', '["Then,", "In fact,", "Likewise,", "For example,"]', 0, 'The correct answer is A. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1002, 'reading_writing', 2, 'expression', 'transitions', 'medium', 'Which choice completes the text with the most logical transition?', 'Arkansas aviator Louise Thaden was already a record breaker when she won the inaugural National Women''s Air
Derby, a race from California to Ohio, in August of 1929. in December of 1928, Thaden had set an aviation
record when she reached an altitude of 20,269 feet in a Travel Air biplane.', '["Earlier,", "However,", "Next,", "As a result,"]', 0, 'The correct answer is A. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1003, 'reading_writing', 1, 'expression', 'transitions', 'medium', 'Which choice completes the text with the most logical transition?', 'With darkness falling, a mother elephant loses sight of her calf and wants to make sure it is safe. she
releases an infrasonic call for the calf to hear. Infrasonic sound is below the range of human hearing, but many
animals can hear these sounds from several miles away.', '["For example,", "For this reason,", "Nowadays,", "Similarly,"]', 1, 'The correct answer is B. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1004, 'reading_writing', 2, 'expression', 'transitions', 'medium', 'Which choice completes the text with the most logical transition?', 'The number of dark spots that appear on the Sun, known as sunspots, can vary greatly. For example, there were
about 180 sunspots in November 2001.___ there were only about 2 sunspots in December 2008.', '["In other words,", "Similarly,", "Therefore,", "By comparison,"]', 3, 'The correct answer is D. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1005, 'reading_writing', 1, 'expression', 'transitions', 'medium', 'Which choice completes the text with the most logical transition?', '"O2 Arena," an award-winning science fiction story by Nigerian author Oghenechovwe Donald Ekpeki, takes place
in an alternate version of Nigeria where breathable air is a rare commodity that is owned and sold by companies.
people must purchase it with currency called O2 credits.', '["As a result,", "In any case,", "Nevertheless,", "Earlier,"]', 0, 'The correct answer is A. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1006, 'reading_writing', 2, 'expression', 'transitions', 'medium', 'Which choice completes the text with the most logical transition?', 'As biologist Terrie Williams has documented, deep dives present a challenge for seals and other marine
mammals. A seal must exert enough energy to propel itself hundreds of meters downward, while keeping its heart
rate low enough that it doesn''t run out of oxygen while underwater. a seal moves its flippers as little as
possible on a deep dive, gliding to conserve energy.', '["In the first place,", "On the other hand,", "For this reason,", "In comparison,"]', 2, 'The correct answer is C. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1007, 'reading_writing', 1, 'expression', 'transitions', 'medium', 'Which choice completes the text with the most logical transition?', 'To explore how blinking affects social interactions, Dutch researchers observed interactions between human
speakers and "listeners" (animated human faces on a screen). The researchers found that when the listeners
blinked slowly, the speakers tended to talk for less time. quicker blinks were associated with longer talking
times.', '["For example,", "Specifically,", "Firstly,", "By contrast,"]', 3, 'The correct answer is D. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1008, 'reading_writing', 2, 'expression', 'transitions', 'medium', 'Which choice completes the text with the most logical transition?', 'In 1891, dancer and choreographer Loie Fuller first performed her celebrated Serpentine Dance, artfully twirling
her long, flowing skirt to create striking visual effects. in 1896, cinema pioneers Auguste and Louis
