INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1040, 'reading_writing', 1, 'expression', 'transitions', 'medium', 'Which choice completes the text with the most logical transition?', 'Scientists long debated the origins of chondrules, tiny glass beads that formed in meteors billions of years ago. For decades,
different theories were proposed, from lightning strikes to powerful rock collisions, but none had sufficient evidentiary
support. scientists found strong evidence that chondrules were formed by shock waves in nearby nebulae.', '["For example,", "Therefore,", "Similarly,", "Finally,"]', 3, 'The correct answer is D. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1041, 'reading_writing', 2, 'expression', 'transitions', 'medium', 'Which choice completes the text with the most logical transition?', 'When, in the 1800s, geologists first realized that much of Earth had once been covered by great sheets of ice,
some theorized that the phenomenon was cyclical, occurring at regular intervals. Each Ice Age is so destructive,
though, that it largely erases the geological evidence of its predecessor. geologists were unable to
confirm the theory of cyclical Ice Ages until the 1960s.', '["Hence,", "Moreover,", "Nevertheless,", "Next,"]', 0, 'The correct answer is A. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1042, 'reading_writing', 1, 'expression', 'transitions', 'medium', 'Which choice completes the text with the most logical transition?', 'In a 2022 analysis of 200 terms, researchers found a broad pattern of valence-dependent mutation for which negative words
saw a faster rate of cognate replacement— the rate at which a word will be replaced over time with a noncognate
form. Adjectives (e.g., "afraid") saw the largest effect; nouns (e.g., "attack"), meanwhile, saw the smallest.', '["for example,", "likewise,", "in addition,", "that is,"]', 3, 'The correct answer is D. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1043, 'reading_writing', 2, 'expression', 'transitions', 'medium', 'Which choice completes the text with the most logical transition?', 'With their distinctive cone shapes and steeply sloping sides, the volcanoes Hverfjall (Iceland) and Toliman (Guatemala) may
look similar from afar. Tehnuka Ilanko and other volcanologists, can tell by how each was formed that Hverfjall is a
cinder cone volcano, while Toliman is a composite volcano.', '["for example,", "in addition,", "therefore,", "though,"]', 3, 'The correct answer is D. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1044, 'reading_writing', 1, 'expression', 'transitions', 'medium', 'Which choice completes the text with the most logical transition?', 'Voting members of the 2002 Latin Grammys were impressed by Banda Cuisillos''s album Puras Rancheras Con Cuisillos and
its contribution to the banda genre, a form of regional Mexican music featuring large ensembles of wind instruments and
drums that first developed in southern and central Mexico in the mid-nineteenth century. they awarded the group the
Best Banda Album award.', '["In contrast,", "Meanwhile,", "Nevertheless,", "Accordingly,"]', 3, 'The correct answer is D. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1045, 'reading_writing', 2, 'expression', 'transitions', 'medium', 'Which choice completes the text with the most logical transition?', 'Scientists were able to isolate a relatively pure sample of selenium in 1817, the same year they first discovered the element''s
existence. the isolation process took longer for molybdenum, which was isolated in its pure form three years after
scientists first discovered it.', '["By contrast,", "Thus,", "Similarly,", "For instance,"]', 0, 'The correct answer is A. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1046, 'reading_writing', 1, 'expression', 'transitions', 'medium', 'Which choice completes the text with the most logical transition?', 'In a heated debate in biogeography, the field is divided between dispersalists and vicariancists. there are
those who argue that dispersal is the most crucial determining factor in a species'' distribution, and those who
insist that vicariance (separation due to geographic barriers) is. Biogeographer Isabel Sanmartin counts herself
among neither.', '["Furthermore,", "By contrast,", "Similarly,", "That is,"]', 3, 'The correct answer is D. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1047, 'reading_writing', 2, 'expression', 'transitions', 'medium', 'Which choice completes the text with the most logical transition?', 'In 1815, while in exile in Jamaica, Venezuelan revolutionary Simon Bolivar penned a letter praising England''s
republican government and expressing hope that Latin American nations seeking independence from Spain might
achieve something similar. The letter was addressed to a local merchant, Henry Cullen; though, Bolivar''s
goal was to persuade political leaders from England and Europe to support his cause.', '["additionally,", "ultimately,", "accordingly,", "consequently,"]', 1, 'The correct answer is B. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1048, 'reading_writing', 1, 'expression', 'transitions', 'medium', 'Which choice completes the text with the most logical transition?', 'In 2009, the Craft and Folk Art Museum in Los Angeles hosted a special exhibition, Suefios/Yume, showcasing the
works of local sculptor Dora de Larios. As suggested by the show''s title (suefios and yume mean "dreams" in
Spanish and Japanese, respectively), de Larios''s art reflects a mix of cultural influences. her work is
grounded in the artistic traditions of both Mexico and Japan.', '["In addition,", "In contrast,", "Specifically,", "Therefore,"]', 2, 'The correct answer is C. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1049, 'reading_writing', 2, 'expression', 'transitions', 'medium', 'Which choice completes the text with the most logical transition?', 'When one looks at the dark craggy vistas in Hitoshi Fugo''s evocative photo series, one''s mind might wander off to
the cratered surfaces of faraway planets. it''s the series'' title, Flying Frying Pan, that brings one back to
Earth, reminding the viewer that each photo is actually a close-up view of a familiar household object: a frying
pan.', '["Consequently,", "Alternatively,", "Ultimately,", "Additionally,"]', 2, 'The correct answer is C. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1050, 'reading_writing', 1, 'expression', 'transitions', 'medium', 'Which choice completes the text with the most logical transition?', 'Plato believed material objects to be crude representations of unseen ideal forms. In his view, such abstract,
nonmaterial forms are the ultimate source of knowledge. Aristotle disagreed, positing that knowledge is best
obtained through direct engagement with the material world; sensory experience of the material is the
ultimate source of knowledge.', '["regardless,", "admittedly,", "in other words,", "meanwhile,"]', 2, 'The correct answer is C. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1051, 'reading_writing', 2, 'expression', 'transitions', 'medium', 'Which choice completes the text with the most logical transition?', 'Magnetic levitation (maglev) trains are suspended above a track by powerful electromagnets, reducing friction
and thus allowing for much faster speeds. Though maglev advocates in the US have long imagined these trains
crisscrossing the country, their dream remains unrealized. of the handful of maglev trains currently in
operation, all are in Asia.', '["In fact,", "To that end,", "Nevertheless,", "That said,"]', 0, 'The correct answer is A. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1052, 'reading_writing', 1, 'expression', 'transitions', 'medium', 'Which choice completes the text with the most logical transition?', 'Iraqi artist Nazik Al-Malaika, celebrated as the first Arabic poet to write in free verse, didn''t reject traditional forms
entirely; her poem "Elegy for a Woman of No Importance" consists of two ten-line stanzas and a standard number
of syllables. Even in this superficially traditional work, Al-Malaika was breaking new ground by
memorializing an anonymous woman rather than a famous man.', '["therefore,", "in fact,", "moreover,", "though,"]', 3, 'The correct answer is D. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1053, 'reading_writing', 2, 'expression', 'transitions', 'medium', 'Which choice completes the text with the most logical transition?', 'A 2017 study of sign language learners tested the role of iconicity—the similarity of a sign to the thing it
represents—in language acquisition. The study found that the greater the iconicity of a sign, the more likely it was
to have been learned. the correlation between acquisition and iconicity was lower than that between
acquisition and another factor studied: sign frequency.', '["In fact,", "In other words,", "Granted,", "As a result,"]', 2, 'The correct answer is C. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1054, 'reading_writing', 1, 'expression', 'transitions', 'medium', 'Which choice completes the text with the most logical transition?', '"Tulip mania"—the rapid rise and sudden fall of the price of tulip bulbs in seventeenth-century Amsterdam—is
often cited as an example of the perils of rampant market speculation. However, recent research has
demonstrated that the episode was neither as frenzied nor as disastrous as has been thought. The popular myth
surrounding it, should be regarded with some skepticism.', '["for example,", "by contrast,", "nevertheless,", "therefore,"]', 3, 'The correct answer is D. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1055, 'reading_writing', 2, 'expression', 'transitions', 'medium', 'Which choice completes the text with the most logical transition?', 'Seismologists Kaiqing Yuan and Barbara Romanowicz have proposed that the magma fueling Iceland''s more than
30 active volcano systems emerges from deep within Earth. The great depths involved—nearly 3,000 km—mark
Iceland''s volcanoes as extreme outliers; many of Earth''s volcanoes are fed by shallow pockets of magma
found less than 15 km below the surface.', '["indeed,", "nevertheless,", "in addition,", "consequently,"]', 0, 'The correct answer is A. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1056, 'reading_writing', 1, 'expression', 'transitions', 'medium', 'Which choice completes the text with the most logical transition?', 'With its clichéd imagery of suburban lawns and power lines, John Ashbery''s 2004 poem "Ignorance of the Law Is
No Excuse" may seem barren terrain for critical analysis. cultural critic Lauren Berlant finds fertile ground
in just its first two stanzas, devoting most of a book chapter to deciphering the "weight of the default space"
Ashbery creates in this poem.', '["Likewise,", "Nonetheless,", "In turn,", "That is,"]', 1, 'The correct answer is B. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1057, 'reading_writing', 2, 'expression', 'transitions', 'medium', 'Which choice completes the text with the most logical transition?', 'The Sun and other stars are powered by nuclear fusion reactions, in which two atoms collide to form a single
heavier atom, releasing energy. Scientists have long believed that fusion has the potential to meet humanity''s
clean energy needs. prior to December 2022, no fusion reaction in a laboratory setting had ever
generated a net energy gain.', '["For this reason,", "Moreover,", "Specifically,", "That said,"]', 3, 'The correct answer is D. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1058, 'reading_writing', 1, 'expression', 'transitions', 'medium', 'Which choice completes the text with the most logical transition?', 'To perform a quad axel, a figure skater must leap into the air and complete four and a half rotations before landing, an
extreme feat. in 2022, when 17-year-old Ilia Malinin landed the first quad axel—considered the most difficult quad
jump—in a high-level competition, the audience was left awestruck.', '["Moreover,", "Fittingly,", "Next,", "However,"]', 1, 'The correct answer is B. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1059, 'reading_writing', 2, 'expression', 'transitions', 'medium', 'Which choice completes the text with the most logical transition?', 'The mineral mtorolite is most commonly found in Zimbabwe. Mtorolite is cryptocrystalline, meaning that its crystalline
structure is so fine that the individual crystals cannot be distinguished by the naked eye or even under a microscope. The
crystals in microcrystalline minerals are also not visible to the naked eye; they can usually be seen under a
microscope.', '["thus,", "for example,", "that said,", "similarly,"]', 2, 'The correct answer is C. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1060, 'reading_writing', 1, 'expression', 'transitions', 'medium', 'Which choice completes the text with the most logical transition?', 'Ugandan American professor Peter Nazareth believed that Elvis Presley''s music is best understood not as a homogeneous
collection but as an anthology (because Elvis showcased the contributions of a wide range of gospel, blues, and rock
artists). Nazareth entitled his college course on Elvis and his music, which focused on Elvis''s many musical
influences, "Elvis as Anthology."', '["To that end,", "In sum,", "That is,", "In addition,"]', 0, 'The correct answer is A. This question requires understanding of transitions concepts.', 'This question tests your understanding of Transitions. Expression of Ideas is one of the key content domains on the SAT.', 'Practice more Transitions problems to strengthen your skills in this area.', 0, 90, '[]');
INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1061, 'reading_writing', 2, 'expression', 'transitions', 'hard', 'Which choice completes the text with the most logical transition?', 'When soil becomes contaminated by toxic metals, it can be removed from the ground and disposed of in a landfill.
contaminated soil can be detoxified via phytoremediation: plants that can withstand high concentrations

of metals absorb the pollutants and store them in their shoots, which are then cut off and safely disposed of,
