INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1062, 'reading_writing', 1, 'expression', 'transitions', 'hard', 'Which choice completes the text with the most logical transition?', 'The Madison is a type of line dance that involves neat rows of dancers performing a repeated sequence of steps in unison.
