INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1064, 'reading_writing', 1, 'expression', 'transitions', 'hard', 'Which choice completes the text with the most logical transition?', 'Modernista architects championed nature in their designs. the wavy staircase and ornate floral tilework of Hospital de
