INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1065, 'reading_writing', 2, 'expression', 'transitions', 'hard', 'Which choice completes the text with the most logical transition?', 'In Asiya Wadud''s 2022 poem "Shorn, Treaded Red," the poet contemplates a painting that has inspired her: Etel Adnan''s 2020
