INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1414, 'math', 1, 'advanced_math', 'nonlinear_functions', 'advanced', 'A right rectangular prism has a height of 9 inches. 
