INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1520, 'math', 2, 'geometry', 'lines_angles_triangles', 'hard', 'In triangle ABC, angle B is a right angle. The length 
