INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1591, 'math', 2, 'problem_solving', 'ratios_rates', 'easy', 'The number of raccoons in a 131-square-mile area is
