INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1600, 'math', 2, 'geometry', 'right_triangles_trig', 'advanced', 'In triangle XYZ, angle Z is a right angle and the
