INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1613, 'reading_writing', 1, 'information_ideas', 'evidence', 'medium', 'Which choice most effectively uses data from the
table to complete the statement?', 'Housing Starts in the US, January–April 2022
(in thousands)
