INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1763, 'math', 2, 'problem_solving', 'percentages', 'hard', 'The population of Greenville increased by 7%
