INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1766, 'math', 2, 'geometry', 'area_volume', 'advanced', 'A certain town has an area of 4.36 square miles.
What is the area, in square yards, of this town?
(1 mile = 1,760 yards)', NULL, '["404", "7,674", "710,459", "13,505,536"]', 3, 'Choice D is correct. Since the number of yards in 1 mile is , 1 760, the number of square yards in 1 square mile is , , , , 1 760 1 760 3 097 600 = ^ ^h h . Therefore, if the area of the town is . 4 36 square miles, it is . , , , , 4 36 3 097 600 13 505 536 = ^ h , in square yards.', 'This is a College Board practice test question. Review the official explanation for detailed analysis.', 'Work through more practice test questions in this section to build familiarity with the test format.', 1, 150, '[]');
