INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1832, 'math', 2, 'advanced_math', 'equivalent_expressions', 'medium', 'Each side of equilateral triangle S is multiplied by a
