INSERT INTO questions (id, section, module, topic, subtopic, difficulty, question_text, passage_text, options, correct_index, explain_why, explain_concept, explain_next, is_calculator_allowed, est_time_sec, tags) VALUES (1834, 'math', 2, 'algebra', 'linear_equations_one_var', 'medium', 'Vivian bought party hats and cupcakes for $71. Each
